import{_ as a,c as n,o as e,b0 as p}from"./chunks/framework.Becqh7-x.js";const l="data:image/png;base64,",r="data:image/png;base64,",o=JSON.parse('{"title":"LV010-异常处理示例","description":null,"frontmatter":{"title":"LV010-异常处理示例","date":"2026-01-15T16:01:38.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/bare/interrupt/126d2cf79c4a213747c98a0f","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-15T16:01:38.531Z","fulluuid":"747c98a0f4f54dea87eb2c766c0021ab","useduuid":"747c98a0f"}},"headers":[],"relativePath":"sdoc/bare/interrupt/126d2cf79c4a213747c98a0f.md","filePath":"sdoc/25-裸机开发/35-中断与异常/LV010-异常处理示例.md","lastUpdated":1768604092000}'),i={name:"sdoc/bare/interrupt/126d2cf79c4a213747c98a0f.md"};function t(c,s,b,A,u,d){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="lv010-异常处理示例" tabindex="-1">LV010-异常处理示例 <a class="header-anchor" href="#lv010-异常处理示例" aria-label="Permalink to &quot;LV010-异常处理示例&quot;">​</a></h1><h2 id="一、svc-异常" tabindex="-1">一、SVC 异常 <a class="header-anchor" href="#一、svc-异常" aria-label="Permalink to &quot;一、SVC 异常&quot;">​</a></h2><h3 id="_1-软中断指令" tabindex="-1">1. 软中断指令 <a class="header-anchor" href="#_1-软中断指令" aria-label="Permalink to &quot;1. 软中断指令&quot;">​</a></h3><p>前边其实有学习过 SWI 指令，我们可以通过这个指令，触发软中断，从而进入 SVC 模式，一般语法如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SWI immed_24</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>immed_24 是一个 24 位立即数，比如 0x123 些。注意：我们使用“ swi”指令，实际上我们可以在 .dis 中看到它被翻译为 SVC 指令。在老的芯片比如 S3C2440 中我们使用 SWI 指令，在 IMX6ULL 中可以使用 SVC 代替它。</p><h3 id="_2-svc-异常处理" tabindex="-1">2. SVC 异常处理 <a class="header-anchor" href="#_2-svc-异常处理" aria-label="Permalink to &quot;2. SVC 异常处理&quot;">​</a></h3><p>当使用 SWI 软中断的时候，就会产生 SVC 异常，进入这个模式，对应的 CPSR 的 M[4:0]的值为 10011，也就是 0x13。关于 SVC 异常的汇编如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* SVC中断 */</span></span>
<span class="line"><span>SVC_Handler:</span></span>
<span class="line"><span>	/** 执行到这里之前:</span></span>
<span class="line"><span>	  * 1. lr_svc保存有被中断模式中的下一条即将执行的指令的地址</span></span>
<span class="line"><span>	  * 2. SPSR_svc保存有被中断模式的CPSR</span></span>
<span class="line"><span>	  * 3. CPSR中的M4-M0被设置为10011, 进入到svc模式</span></span>
<span class="line"><span>	  * 4. 跳到0x08的地方执行程序 </span></span>
<span class="line"><span>	  */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	/* 保存现场 */</span></span>
<span class="line"><span>	/* 在swi异常处理函数中有可能会修改r0-r12, 所以先保存 */</span></span>
<span class="line"><span>	/* lr是异常处理完后的返回地址, 也要保存 */</span></span>
<span class="line"><span>	stmdb sp!, {r0-r12, lr}  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>	mov r4, lr</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	/* 处理swi异常 */</span></span>
<span class="line"><span>	mrs r0, cpsr</span></span>
<span class="line"><span>	ldr r1, =swi_string</span></span>
<span class="line"><span>	bl printException</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	sub r0, r4, #4</span></span>
<span class="line"><span>	bl printSWIVal</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	/* 恢复现场 */</span></span>
<span class="line"><span>	ldmia sp!, {r0-r12, pc}^  /* ^会把spsr的值恢复到cpsr里 */</span></span>
<span class="line"><span>swi_string:</span></span>
<span class="line"><span>	.string &quot;swi exception&quot;</span></span>
<span class="line"><span>	.align 4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br></div></div><p>在 SVC_Handler 里将 r0-r12 和 lr 保存在 SVC 模式的栈上，然后将 lr 的值移动到 R4，调用 printException 函数打印出当前的 CPSR 值，和产生异常的原因。将 R4 减去 4，赋值给 R0，这是 swi 指令所在的地址，然后调用 printSWIVal 函数打印出 swi 指令的参数。最后将 r0-r12 从栈上恢复， lr 从栈上弹出到 PC，并同时将 SPSR 恢复到 CPSR，从而返回去执行 swi 指令的下一条指令。</p><h3 id="_3-设置堆栈" tabindex="-1">3. 设置堆栈 <a class="header-anchor" href="#_3-设置堆栈" aria-label="Permalink to &quot;3. 设置堆栈&quot;">​</a></h3><p>注意一定要设置堆栈，否则进入对应的异常后，堆栈可能会异常。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	/* 进入SVC模式 */</span></span>
<span class="line"><span>	mrs r0, cpsr</span></span>
<span class="line"><span>	bic r0, r0, #0x1f 	/* 将r0寄存器中的低5位清零，也就是cpsr的M0~M4 	*/</span></span>
<span class="line"><span>	orr r0, r0, #0x13 	/* r0或上0x13,表示使用SVC模式					*/</span></span>
<span class="line"><span>	msr cpsr, r0		/* 将r0 的数据写入到cpsr_c中 					*/</span></span>
<span class="line"><span>	ldr sp, =0X80200000	/* 设置SVC模式下的栈首地址为0X80200000,大小为2MB */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_4-完整实例" tabindex="-1">4. 完整实例 <a class="header-anchor" href="#_4-完整实例" aria-label="Permalink to &quot;4. 完整实例&quot;">​</a></h3><p>完整的实例及修改可以看这里：<a href="https://gitee.com/linux-dev-org/imx6ull-bare-demo/tree/main/08_EXCEPTION/SWI" target="_blank" rel="noreferrer">08_EXCEPTION/SWI · sumumm/imx6ull-bare-demo</a></p><h3 id="_5-测试结果" tabindex="-1">5. 测试结果 <a class="header-anchor" href="#_5-测试结果" aria-label="Permalink to &quot;5. 测试结果&quot;">​</a></h3><p>我们可以在终端看到以下打印信息：</p><img src="`+l+`" alt="image-20240118215617370" style="zoom:50%;"><h2 id="二、未定义异常" tabindex="-1">二、未定义异常 <a class="header-anchor" href="#二、未定义异常" aria-label="Permalink to &quot;二、未定义异常&quot;">​</a></h2><h3 id="_1-怎么产生未定义异常" tabindex="-1">1. 怎么产生未定义异常？ <a class="header-anchor" href="#_1-怎么产生未定义异常" aria-label="Permalink to &quot;1. 怎么产生未定义异常？&quot;">​</a></h3><p>前边已经学习过了，就是 CPU 或协处理器不认识这条指令，执行这样的指令时就会产生“未定义指令异常”。 我们可以这样产生一个未定义异常：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.word 0xeeadc0de  /* undefine instruction */</span></span>
<span class="line"><span>.word 0xFFFFFFFF</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>上边两条都可以产生未定义异常。</p><h3 id="_2-未定义异常处理" tabindex="-1">2. 未定义异常处理 <a class="header-anchor" href="#_2-未定义异常处理" aria-label="Permalink to &quot;2. 未定义异常处理&quot;">​</a></h3><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Undefined_Handler:</span></span>
<span class="line"><span>	/** 执行到这里之前:</span></span>
<span class="line"><span>	  * 1. lr_und保存有被中断模式中的下一条即将执行的指令的地址</span></span>
<span class="line"><span>	  * 2. SPSR_und保存有被中断模式的CPSR</span></span>
<span class="line"><span>	  * 3. CPSR中的M4-M0被设置为11011, 进入到und模式</span></span>
<span class="line"><span>	  * 4. 跳到0x4的地方执行程序 </span></span>
<span class="line"><span>	  */</span></span>
<span class="line"><span></span></span>
<span class="line"><span>	/* 在und异常处理函数中有可能会修改r0-r12, 所以先保存 */</span></span>
<span class="line"><span>	/* lr是异常处理完后的返回地址, 也要保存 */</span></span>
<span class="line"><span>	stmdb sp!, {r0-r12, lr}  </span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	/* 保存现场 */</span></span>
<span class="line"><span>	/* 处理und异常 */</span></span>
<span class="line"><span>	mrs r0, cpsr</span></span>
<span class="line"><span>	ldr r1, =und_string</span></span>
<span class="line"><span>	bl printException</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	/* 恢复现场 */</span></span>
<span class="line"><span>	ldmia sp!, {r0-r12, pc}^  /* ^会把spsr的值恢复到cpsr里 */</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>und_string:</span></span>
<span class="line"><span>	.string &quot;undefined instruction exception&quot;</span></span>
<span class="line"><span>	.align 4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>在 Undefined_Handler 里将 r0-r12 和 lr 保存在 und 模式的栈上，然后调用 printException 打印当前的 CPSR 值，并打印一个字符串。最后将 r0-r12 从栈上恢复， lr 从栈上弹出到 PC，并同时将 SPSR 恢复到 CPSR，从而返回去执行出现未定义异常指令的下一条指令。</p><h3 id="_3-设置堆栈-1" tabindex="-1">3. 设置堆栈 <a class="header-anchor" href="#_3-设置堆栈-1" aria-label="Permalink to &quot;3. 设置堆栈&quot;">​</a></h3><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>	/* 进入undef模式 */</span></span>
<span class="line"><span>	mrs r0, cpsr</span></span>
<span class="line"><span>	bic r0, r0, #0x1f 	/* 将r0寄存器中的低5位清零，也就是cpsr的M0~M4 	*/</span></span>
<span class="line"><span>	orr r0, r0, #0x1B 	/* r0或上0x1B,表示使用undef模式					*/</span></span>
<span class="line"><span>	msr cpsr, r0		/* 将r0 的数据写入到cpsr_c中 					*/</span></span>
<span class="line"><span>	ldr sp, =0x80800000	/* 设置IRQ模式下的栈首地址为0X80600000,大小为2MB */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_4-完整实例-1" tabindex="-1">4. 完整实例 <a class="header-anchor" href="#_4-完整实例-1" aria-label="Permalink to &quot;4. 完整实例&quot;">​</a></h3><p>完整的实例和修改的地方可以看这里：<a href="https://gitee.com/linux-dev-org/imx6ull-bare-demo/tree/main/08_EXCEPTION/UNDEF" target="_blank" rel="noreferrer">08_EXCEPTION/UNDEF · sumumm/imx6ull-bare-demo </a></p><h3 id="_5-测试结果-1" tabindex="-1">5. 测试结果 <a class="header-anchor" href="#_5-测试结果-1" aria-label="Permalink to &quot;5. 测试结果&quot;">​</a></h3><p>最终我们可以在终端看到以下打印信息：</p><img src="`+r+'" alt="image-20240118221514998" style="zoom:50%;">',33)])])}const h=a(i,[["render",t]]);export{o as __pageData,h as default};
